    C.append(wr('hard', 'lcm', 'រកចំនួនគត់ពីរខ្ទង់តូចបំផុតដែលចែកដាច់នឹង ' + M(4) + ' ផង ' + M(6) + ' ផង និង ' + M(9) + ' ផង។', [(M('4 = 2^2, 6 = 2 \\times 3, 9 = 3^2'), 1), (M('LCM(4, 6, 9) = 2^2 \\times 3^2 = 36'), 2), ('ពហុគុណរួមទាំងអស់គឺពហុគុណនៃ ' + M(36) + ' ៖ ' + M('36, 72, 108, \\dots'), 1), ('ចំនួនពីរខ្ទង់តូចបំផុតគឺ ' + M(36), 1)]))
    return C
